package com.trackpadcamera;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TrackpadCameraPluginLauncher {
    public static void main(String[] args) throws Exception {
        ExternalPluginManager.loadBuiltin(TrackpadCameraPlugin.class);
        RuneLite.main(args);
    }
}

package com.trackpadcamera;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.awt.Component;
import java.awt.event.InputEvent;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.lang.reflect.Field;

import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TrackpadCameraPluginTest {

    private TrackpadCameraPlugin plugin;
    private Client client;
    private TrackpadCameraConfig config;

    @Before
    public void setUp() throws Exception {
        plugin = new TrackpadCameraPlugin();
        client = mock(Client.class);
        config = mock(TrackpadCameraConfig.class);

        inject(plugin, "client", client);
        inject(plugin, "config", config);

        when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
        when(client.getCameraYaw()).thenReturn(4096);
        when(client.getCameraPitch()).thenReturn(2800);

        when(config.enableRotation()).thenReturn(true);
        when(config.enableTilt()).thenReturn(true);
        when(config.invertRotation()).thenReturn(false);
        when(config.invertTilt()).thenReturn(false);
        when(config.invertZoom()).thenReturn(false);
        when(config.rotationSensitivity()).thenReturn(5);
        when(config.tiltSensitivity()).thenReturn(5);
    }

    // --- Helpers ---

    private static void inject(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static MouseWheelEvent trackpadSwipe(double delta, int modifiers, boolean ctrl) {
        MouseWheelEvent event = mock(MouseWheelEvent.class);
        when(event.getPreciseWheelRotation()).thenReturn(delta);
        when(event.getWheelRotation()).thenReturn(0);
        when(event.getModifiersEx()).thenReturn(modifiers);
        when(event.isControlDown()).thenReturn(ctrl);
        return event;
    }

    private static MouseWheelEvent scrollWheelClick() {
        MouseWheelEvent event = mock(MouseWheelEvent.class);
        when(event.getPreciseWheelRotation()).thenReturn(3.0);
        when(event.getWheelRotation()).thenReturn(3);
        when(event.getModifiersEx()).thenReturn(0);
        return event;
    }

    // --- Scroll wheel pass-through ---

    @Test
    public void scrollWheelEventPassesThrough() {
        // A physical scroll wheel event (no SHIFT/CTRL, invertZoom off) must not be consumed
        // and must not trigger any camera action — OSRS handles zoom natively
        MouseWheelEvent event = scrollWheelClick();
        plugin.mouseWheelMoved(event);
        verify(event, never()).consume();
        verify(client, never()).setCameraYawTarget(anyInt());
        verify(client, never()).setCameraPitchTarget(anyInt());
    }

    // --- Gesture routing ---

    @Test
    public void verticalSwipePassesThrough() {
        // Plain two-finger vertical scroll passes through for OSRS zoom
        MouseWheelEvent event = trackpadSwipe(0.5, 0, false);
        plugin.mouseWheelMoved(event);
        verify(event, never()).consume();
        verify(client, never()).setCameraPitchTarget(anyInt());
    }

    @Test
    public void horizontalSwipeUpdatesYaw() {
        MouseWheelEvent event = trackpadSwipe(0.5, InputEvent.SHIFT_DOWN_MASK, false);
        plugin.mouseWheelMoved(event);
        verify(client).setCameraYawTarget(anyInt());
        verify(event).consume();
    }

    @Test
    public void ctrlScrollUpdatesPitch() {
        // Ctrl + two-finger scroll tilts camera pitch
        MouseWheelEvent event = trackpadSwipe(0.5, 0, true);
        plugin.mouseWheelMoved(event);
        verify(client).setCameraPitchTarget(anyInt());
        verify(event).consume();
    }

    // --- Game state guard ---

    @Test
    public void noActionWhenNotLoggedIn() {
        when(client.getGameState()).thenReturn(GameState.LOGIN_SCREEN);
        MouseWheelEvent event = trackpadSwipe(0.5, 0, true);
        plugin.mouseWheelMoved(event);
        verify(client, never()).setCameraPitchTarget(anyInt());
        verify(event, never()).consume();
    }

    // --- Config toggles ---

    @Test
    public void disabledTiltSkipsPitchUpdate() {
        when(config.enableTilt()).thenReturn(false);
        MouseWheelEvent event = trackpadSwipe(0.5, 0, true);
        plugin.mouseWheelMoved(event);
        verify(client, never()).setCameraPitchTarget(anyInt());
    }

    // --- Zoom inversion ---

    @Test
    public void invertZoomConsumesOriginalEvent() {
        // invertZoom=true — original event must be consumed so OSRS sees only the re-dispatched inverted one
        when(config.invertZoom()).thenReturn(true);
        MouseWheelEvent event = new MouseWheelEvent(
            mock(Component.class), MouseEvent.MOUSE_WHEEL, System.currentTimeMillis(),
            0, 0, 0, 0, 0, 0, false, MouseWheelEvent.WHEEL_UNIT_SCROLL, 1, 0, 0.5
        );
        plugin.mouseWheelMoved(event);
        assertTrue("Zoom inversion must consume the original event", event.isConsumed());
    }

    @Test
    public void noInvertZoomPassesThroughVerticalScroll() {
        // invertZoom=false (default) — vertical scroll must not be consumed
        MouseWheelEvent event = trackpadSwipe(0.5, 0, false);
        plugin.mouseWheelMoved(event);
        verify(event, never()).consume();
    }

    @Test
    public void disabledRotationSkipsYawUpdate() {
        when(config.enableRotation()).thenReturn(false);
        MouseWheelEvent event = trackpadSwipe(0.5, InputEvent.SHIFT_DOWN_MASK, false);
        plugin.mouseWheelMoved(event);
        verify(client, never()).setCameraYawTarget(anyInt());
    }

    // --- Value clamping ---

    @Test
    public void pitchClampedToMax() {
        when(client.getCameraPitch()).thenReturn(4080);
        MouseWheelEvent event = trackpadSwipe(5.0, 0, true);
        plugin.mouseWheelMoved(event);
        ArgumentCaptor<Integer> captor = ArgumentCaptor.forClass(Integer.class);
        verify(client).setCameraPitchTarget(captor.capture());
        assertTrue("Pitch must not exceed 4096", captor.getValue() <= 4096);
    }

    @Test
    public void pitchClampedToMin() {
        when(client.getCameraPitch()).thenReturn(1040);
        MouseWheelEvent event = trackpadSwipe(-5.0, 0, true);
        plugin.mouseWheelMoved(event);
        ArgumentCaptor<Integer> captor = ArgumentCaptor.forClass(Integer.class);
        verify(client).setCameraPitchTarget(captor.capture());
        assertTrue("Pitch must not go below 1024", captor.getValue() >= 1024);
    }

    @Test
    public void yawWrapsWithinRange() {
        when(client.getCameraYaw()).thenReturn(16360);
        when(config.rotationSensitivity()).thenReturn(20);
        MouseWheelEvent event = trackpadSwipe(1.0, InputEvent.SHIFT_DOWN_MASK, false);
        plugin.mouseWheelMoved(event);
        ArgumentCaptor<Integer> captor = ArgumentCaptor.forClass(Integer.class);
        verify(client).setCameraYawTarget(captor.capture());
        int yaw = captor.getValue();
        assertTrue("Yaw must be in range [0, 16384)", yaw >= 0 && yaw < 16384);
    }

    @Test
    public void disabledTiltDoesNotConsumeVerticalScroll() {
        // Even with tilt disabled, plain vertical scroll must still pass through
        when(config.enableTilt()).thenReturn(false);
        MouseWheelEvent event = trackpadSwipe(0.5, 0, false);
        plugin.mouseWheelMoved(event);
        verify(event, never()).consume();
    }

    // --- Inversion ---

    @Test
    public void invertRotationReversesYawDirection() {
        when(config.invertRotation()).thenReturn(true);
        when(client.getCameraYaw()).thenReturn(4096);
        MouseWheelEvent forward = trackpadSwipe(1.0, InputEvent.SHIFT_DOWN_MASK, false);
        plugin.mouseWheelMoved(forward);

        when(config.invertRotation()).thenReturn(false);
        when(client.getCameraYaw()).thenReturn(4096);
        plugin = new TrackpadCameraPlugin();
        try { inject(plugin, "client", client); inject(plugin, "config", config); } catch (Exception e) { throw new RuntimeException(e); }
        MouseWheelEvent normal = trackpadSwipe(1.0, InputEvent.SHIFT_DOWN_MASK, false);
        plugin.mouseWheelMoved(normal);

        ArgumentCaptor<Integer> captor = ArgumentCaptor.forClass(Integer.class);
        verify(client, org.mockito.Mockito.times(2)).setCameraYawTarget(captor.capture());
        int invertedYaw = captor.getAllValues().get(0);
        int normalYaw = captor.getAllValues().get(1);
        assertTrue("Inverted yaw should differ from normal yaw", invertedYaw != normalYaw);
    }

    @Test
    public void invertTiltReversesPitchDirection() {
        when(config.invertTilt()).thenReturn(true);
        when(client.getCameraPitch()).thenReturn(2800);
        MouseWheelEvent invertedEvent = trackpadSwipe(1.0, 0, true);
        plugin.mouseWheelMoved(invertedEvent);
        ArgumentCaptor<Integer> captor = ArgumentCaptor.forClass(Integer.class);
        verify(client).setCameraPitchTarget(captor.capture());
        int invertedPitch = captor.getValue();
        assertTrue("Inverted tilt should decrease pitch for positive delta", invertedPitch < 2800);
    }

}

package com.trackpadcamera;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("trackpadcamera")
public interface TrackpadCameraConfig extends Config {

    @ConfigSection(
        name = "Zoom",
        description = "Enable \"Use Scroll Wheel to Zoom\" in OSRS Settings > Controls > Camera",
        position = 0,
        closedByDefault = false
    )
    String ZOOM_SECTION = "zoomSection";

    @ConfigSection(
        name = "Rotation",
        description = "Two-finger swipe left/right",
        position = 1,
        closedByDefault = false
    )
    String ROTATION_SECTION = "rotationSection";

    @ConfigSection(
        name = "Tilt",
        description = "Ctrl + two-finger scroll up/down",
        position = 2,
        closedByDefault = false
    )
    String TILT_SECTION = "tiltSection";

    // ---- Zoom ----

    @ConfigItem(
        keyName = "invertZoom",
        name = "Invert",
        description = "Reverses the scroll direction for zooming — scroll up zooms out instead of in",
        section = TrackpadCameraConfig.ZOOM_SECTION,
        position = 1
    )
    default boolean invertZoom() {
        return false;
    }

    // ---- Rotation ----

    @ConfigItem(
        keyName = "enableRotation",
        name = "Enable Rotation",
        description = "Two-finger horizontal swipe to rotate camera yaw",
        section = TrackpadCameraConfig.ROTATION_SECTION,
        position = 0
    )
    default boolean enableRotation() {
        return true;
    }

    @ConfigItem(
        keyName = "invertRotation",
        name = "Invert",
        description = "Reverse the rotation direction",
        section = TrackpadCameraConfig.ROTATION_SECTION,
        position = 1
    )
    default boolean invertRotation() {
        return false;
    }

    @Range(min = 1, max = 20)
    @ConfigItem(
        keyName = "rotationSensitivity",
        name = "Sensitivity",
        description = "How fast the camera rotates with horizontal swipes",
        section = TrackpadCameraConfig.ROTATION_SECTION,
        position = 2
    )
    default int rotationSensitivity() {
        return 5;
    }

    // ---- Tilt ----

    @ConfigItem(
        keyName = "enableTilt",
        name = "Enable Tilt",
        description = "Ctrl + two-finger scroll up/down to tilt camera pitch",
        section = TrackpadCameraConfig.TILT_SECTION,
        position = 0
    )
    default boolean enableTilt() {
        return true;
    }

    @ConfigItem(
        keyName = "invertTilt",
        name = "Invert",
        description = "Reverse the tilt direction",
        section = TrackpadCameraConfig.TILT_SECTION,
        position = 1
    )
    default boolean invertTilt() {
        return false;
    }

    @Range(min = 1, max = 20)
    @ConfigItem(
        keyName = "tiltSensitivity",
        name = "Sensitivity",
        description = "How fast the camera tilts with ctrl + two-finger scroll",
        section = TrackpadCameraConfig.TILT_SECTION,
        position = 2
    )
    default int tiltSensitivity() {
        return 5;
    }
}

package com.trackpadcamera;

import com.google.inject.Provides;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;

@PluginDescriptor(
    name = "Trackpad Camera",
    description = "Mac trackpad camera controls: swipe left/right to rotate, ctrl+scroll to tilt. Zoom via OSRS scroll setting.",
    tags = {"camera", "trackpad", "mac", "gesture"}
)
public class TrackpadCameraPlugin extends Plugin implements MouseWheelListener, MouseListener {

    @Inject
    private Client client;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private TrackpadCameraConfig config;

    // Sensitivity multiplier applied on top of config sensitivity
    private static final double ROTATE_SENSITIVITY = 24.0;

    // Guards against re-processing the inverted scroll event we dispatch for invertZoom.
    private boolean dispatchingInvertedScroll = false;

    @Override
    protected void startUp() {
        mouseManager.registerMouseWheelListener(this);
        mouseManager.registerMouseListener(this);
    }

    @Override
    protected void shutDown() {
        mouseManager.unregisterMouseWheelListener(this);
        mouseManager.unregisterMouseListener(this);
    }

    @Provides
    TrackpadCameraConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(TrackpadCameraConfig.class);
    }

    @Override
    public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e) {
        if (client.getGameState() != GameState.LOGGED_IN) {
            return e;
        }

        // Skip re-processing the inverted event we dispatched for invertZoom
        if (dispatchingInvertedScroll) {
            dispatchingInvertedScroll = false;
            return e;
        }

        double preciseRotation = e.getPreciseWheelRotation();
        boolean isHorizontal = (e.getModifiersEx() & java.awt.event.InputEvent.SHIFT_DOWN_MASK) != 0;

        if (isHorizontal) {
            // Two-finger horizontal swipe → rotate camera yaw
            if (config.enableRotation()) {
                double delta = preciseRotation * config.rotationSensitivity()
                    * (config.invertRotation() ? -1 : 1);
                rotateCameraYaw(delta);
                e.consume();
            }
        } else if (e.isControlDown()) {
            // Ctrl + two-finger scroll up/down → tilt camera pitch
            if (config.enableTilt()) {
                double delta = preciseRotation * config.tiltSensitivity()
                    * (config.invertTilt() ? -1 : 1);
                rotateCameraPitch(delta);
                e.consume();
            }
        } else if (config.invertZoom()) {
            // Invert scroll direction by consuming the original and re-dispatching with negated values
            e.consume();
            dispatchingInvertedScroll = true;
            e.getComponent().dispatchEvent(new MouseWheelEvent(
                e.getComponent(), e.getID(), e.getWhen(), e.getModifiersEx(),
                e.getX(), e.getY(), e.getXOnScreen(), e.getYOnScreen(),
                e.getClickCount(), e.isPopupTrigger(),
                e.getScrollType(), e.getScrollAmount(),
                -e.getWheelRotation(), -e.getPreciseWheelRotation()
            ));
        }
        // Plain vertical scroll with invertZoom=false passes through for OSRS native zoom

        return e;
    }

    /**
     * Rotates the camera horizontally (yaw).
     * Camera yaw ranges 0-16383 in OSRS JAU14 units.
     */
    private void rotateCameraYaw(double delta) {
        int currentYaw = client.getCameraYaw();
        int newYaw = (currentYaw + (int)(delta * ROTATE_SENSITIVITY)) & 0x3fff;
        client.setCameraYawTarget(newYaw);
    }

    /**
     * Tilts the camera vertically (pitch).
     * Pitch ranges roughly 1024-4096 in OSRS JAU14 units.
     * (lower = more overhead, higher = more horizontal).
     */
    private void rotateCameraPitch(double delta) {
        int currentPitch = client.getCameraPitch();
        int newPitch = currentPitch + (int)(delta * ROTATE_SENSITIVITY);
        newPitch = Math.max(1024, Math.min(4096, newPitch));
        client.setCameraPitchTarget(newPitch);
    }

    // ---- MouseListener required methods (pass-through) ----

    @Override
    public MouseEvent mouseClicked(MouseEvent e) { return e; }

    @Override
    public MouseEvent mousePressed(MouseEvent e) { return e; }

    @Override
    public MouseEvent mouseReleased(MouseEvent e) { return e; }

    @Override
    public MouseEvent mouseEntered(MouseEvent e) { return e; }

    @Override
    public MouseEvent mouseExited(MouseEvent e) { return e; }

    @Override
    public MouseEvent mouseDragged(MouseEvent e) { return e; }

    @Override
    public MouseEvent mouseMoved(MouseEvent e) { return e; }
}
